// ── PC-Volldiagnose: Befund-Typen und ihre Lösungswege ───────────────────────
// Grundsatz: JEDER Befund-Typ hat mindestens einen Lösungsweg (Aktion, Katalogproblem,
// Werkzeug oder Hinweis bei Handarbeit). Ist die Ursache offen, nennt er eine Vertiefung.
// Der Abdeckungstest (.tmp-test/vd/abdeckung_test.ts) prüft das für alle Typen und dass jede
// verknüpfte Aktion, jedes Problem und jedes Werkzeug existiert.
// Typen der geführten Diagnose („dg:<problem>“) und unbekannte Ereignisse bekommen ihren
// Lösungsweg dynamisch aus dem Problem-Katalog (siehe befunde.ts).

import type { VdBereich, VdFachdiagnose, VdLoesung, VdPhase, VdSchritt, VdSchwere } from './typen'

export interface VdTyp {
  typ: string
  titel: string
  /** Was bedeutet das — für den Admin, ohne Fachchinesisch */
  erklaerung: string
  schwere: VdSchwere
  bereich: VdBereich
  ursacheOffen?: boolean
  vertiefungen?: string[]
  fachdiagnose?: VdFachdiagnose
  loesungen: VdLoesung[]
  /** Zusätzlich das passende Katalogproblem anbieten (fest) … */
  problem?: string
  /** … bzw. per Suchtext für „Gib dein Problem ein“ (nur bei sicherem Treffer) */
  suche?: string
  /**
   * Katalogproblem in „Gib dein Problem ein“, das DIESEN Lösungsweg ebenfalls enthält (Nutzerwunsch
   * 16.11.2026: Lösungswege auch dort hinterlegen). Anders als `problem` ändert es die Lösungen der
   * Diagnose nicht – sonst stünden sie doppelt da. Gesetzt über IM_KATALOG unten; der Test
   * .tmp-test/vd/pa_abdeckung_test.ts prüft, dass das Problem den Lösungsweg wirklich enthält.
   */
  imKatalog?: string
}

// ── Bausteine für Lösungen ───────────────────────────────────────────────────
type Opt = { dauer?: string; neustart?: boolean; frage?: VdLoesung['frage'] }
function akt(id: string, titel: string, schritte: (string | VdSchritt)[], phase: VdPhase, wirkung: string, o: Opt = {}): VdLoesung {
  return { id, titel, art: 'aktionen', schritte: schritte.map(s => (typeof s === 'string' ? { aktion: s } : s)), phase, wirkung, ...o }
}
function wz(werkzeug: string, titel: string, wirkung: string, phase: VdPhase = 'konfiguration'): VdLoesung {
  return { id: 'wz-' + werkzeug, titel, art: 'werkzeug', werkzeug, phase, wirkung }
}
function hin(id: string, titel: string, hinweis: string, phase: VdPhase = 'konfiguration'): VdLoesung {
  return { id: 'hin-' + id, titel, art: 'hinweis', hinweis, phase, wirkung: hinweis }
}
/** Hinweis nur auf Servern zeigen (am PC wäre er Rauschen). */
const nurServer = (l: VdLoesung): VdLoesung => ({ ...l, nur: 'server' })

